import sys
def _fail(t, e, tb, _d=sys.excepthook):
    if issubclass(t, AssertionError):
        print('check failed:', e); sys.exit(1)
    _d(t, e, tb)
sys.excepthook = _fail
import re, glob, os, ast, subprocess
tracked = set(subprocess.run(['git', 'ls-files'], capture_output=True, text=True).stdout.split())
tests = set()
for f in glob.glob('_tools/test_*.py'):
    tests |= {n.name for n in ast.walk(ast.parse(open(f, encoding='utf-8').read())) if isinstance(n, ast.FunctionDef)}
files = {os.path.splitext(os.path.basename(p))[0] for p in tracked}
docs = glob.glob('kb/_self/*.md') + ['AGENTS.md', 'README.md'] + glob.glob('skills/*/SKILL.md') + glob.glob('.claude/skills/*/SKILL.md') + glob.glob('agents/*.md')
ok = {'_tools/test_x.py', 'test_x', 'test_file'}
bad = []
for d in docs:
    s = open(d, encoding='utf-8').read()
    for m in re.findall(r'(?<![\w/.-])(_tools/[\w./-]+\.(?:py|json|txt|csv|toml))', s):
        if m not in tracked and m not in ok: bad.append((d, m))
    for m in set(re.findall(r'\b(test_[a-z0-9_]+)\b', s)):
        if m not in tests and m not in files and m not in ok: bad.append((d, m))
print('removed tools or tests the docs still name:', sorted(set(bad))); sys.exit(1 if bad else 0)
